const lessons=[{"sentences":[{"speaker":"A","text":"I feel so stressed because our final exams are coming very soon.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.695708333333333},{"speaker":"B","text":"You worked too hard last week and that caused your burnout.","position":2,"audioStartSeconds":4.895708333333333,"audioEndSeconds":8.689375},{"speaker":"A","text":"If I study every single night without any breaks I get exhausted.","position":3,"audioStartSeconds":8.889375,"audioEndSeconds":13.387583333333334},{"speaker":"B","text":"We need to create a realistic schedule that includes proper rest.","position":4,"audioStartSeconds":13.587583333333333,"audioEndSeconds":17.982666666666667},{"speaker":"A","text":"Although my parents want me to study four hours daily that feels impossible.","position":5,"audioStartSeconds":18.182666666666666,"audioEndSeconds":23.00225},{"speaker":"B","text":"Two focused hours with short breaks are much more effective than four.","position":6,"audioStartSeconds":23.20225,"audioEndSeconds":27.686791666666668},{"speaker":"A","text":"When should we wake up to review our difficult chemistry notes?","position":7,"audioStartSeconds":27.886791666666667,"audioEndSeconds":31.739875},{"speaker":"B","text":"Morning sessions work best because our minds stay completely fresh then.","position":8,"audioStartSeconds":31.939875,"audioEndSeconds":36.57904166666667},{"speaker":"A","text":"Shall we meet at the campus library every Tuesday and Thursday afternoon?","position":9,"audioStartSeconds":36.779041666666664,"audioEndSeconds":41.30225},{"speaker":"B","text":"The library is often noisy so my quiet apartment is much better.","position":10,"audioStartSeconds":41.50225,"audioEndSeconds":46.02545833333333},{"speaker":"A","text":"That sounds peaceful since your neighborhood has very little traffic noise.","position":11,"audioStartSeconds":46.225458333333336,"audioEndSeconds":50.864625},{"speaker":"B","text":"We can share flashcards and test each other on difficult vocabulary.","position":12,"audioStartSeconds":51.064625,"audioEndSeconds":55.690916666666666},{"speaker":"A","text":"Have you already prepared the biology questions for our practice test?","position":13,"audioStartSeconds":55.89091666666667,"audioEndSeconds":60.414125},{"speaker":"B","text":"I have finished half of them and will complete the rest tonight.","position":14,"audioStartSeconds":60.614125,"audioEndSeconds":64.389875},{"speaker":"A","text":"This new plan makes me feel much more confident about passing.","position":15,"audioStartSeconds":64.589875,"audioEndSeconds":68.91341666666666},{"speaker":"B","text":"Let us start our first revision session tomorrow morning after breakfast.","position":16,"audioStartSeconds":69.11341666666667,"audioEndSeconds":73.8195}],"questions":[{"prompt":"Why did speaker A feel exhausted last week?","options":["Because of studying every night without breaks.","Because of working four hours every morning.","Because of noisy traffic near the library."],"answer":"A","evidenceSentence":3,"evidence":"If I study every single night without any breaks I get exhausted","explanation":"Người nói A giải thích rằng việc học mỗi đêm mà không nghỉ ngơi khiến họ kiệt sức."},{"prompt":"What is the main purpose of this conversation?","options":["To complain about strict parents.","To plan a better study routine.","To prepare for a chemistry exam."],"answer":"B","evidenceSentence":4,"evidence":"We need to create a realistic schedule","explanation":"Hai người bạn đang thảo luận để lập ra một lịch trình học tập thực tế và hiệu quả hơn sau một tuần mệt mỏi."},{"prompt":"How long does speaker B suggest they study each day?","options":["Four hours.","Two hours.","Half an hour."],"answer":"B","evidenceSentence":6,"evidence":"Two focused hours with short breaks","explanation":"Người nói B gợi ý học tập trung trong hai tiếng cùng với các khoảng nghỉ ngắn."},{"prompt":"Where do they decide to hold their study sessions?","options":["At the campus library.","At speaker A's house.","At speaker B's apartment."],"answer":"C","evidenceSentence":10,"evidence":"my quiet apartment is much better","explanation":"Thư viện quá ồn nên họ quyết định chọn căn hộ yên tĩnh của người nói B làm nơi học."},{"prompt":"What study material does speaker B still need to finish?","options":["The chemistry notes.","The biology questions.","The English flashcards."],"answer":"B","evidenceSentence":14,"evidence":"finished half of them and will complete the rest","explanation":"Người nói B cho biết đã làm xong một nửa số câu hỏi sinh học và sẽ hoàn thành phần còn lại vào tối nay."},{"prompt":"What will the two friends do tomorrow morning?","options":["Start their first revision session.","Visit the campus library together.","Talk with their parents about exams."],"answer":"A","evidenceSentence":16,"evidence":"Let us start our first revision session tomorrow morning","explanation":"Họ thống nhất sẽ bắt đầu buổi ôn tập đầu tiên vào sáng ngày mai sau bữa sáng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
